const locale=(l:Lang)=>({fr:'fr-CA',en:'en-CA',es:'es-CA',ar:'ar-CA'}[l]);
const moneyFor=(cents:number,lang:Lang)=>new Intl.NumberFormat(locale(lang),{minimumFractionDigits:cents%100?2:0,maximumFractionDigits:2}).format(cents/100)+' $';
const tz='America/Toronto';
const dayFormatter=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'});
const zoneFormatter=new Intl.DateTimeFormat('sv-SE',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});
function dayKey(seconds:number){const p=dayFormatter.formatToParts(new Date(seconds*1000));return ['year','month','day'].map(k=>p.find(x=>x.type===k)!.value).join('-')}
function zonedEpoch(day:string,time:string){const initial=new Date(day+'T'+time+':00Z').getTime();let guess=initial;for(let i=0;i<3;i++){const parts=zoneFormatter.formatToParts(new Date(guess));const get=(key:string)=>parts.find(x=>x.type===key)!.value;const rendered=Date.UTC(+get('year'),+get('month')-1,+get('day'),+get('hour'),+get('minute'),+get('second'));guess+=initial-rendered}return guess/1000}
const mail=(subject:string,body:string)=>'mailto:francoroute@outlook.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);
function LinkButton({to,children,kind='',...p}:any){return <a href={routeHref(to)} className={'btn '+kind} {...p}>{children}<ArrowRight size={17}/></a>}
function Eyebrow({children}:any){return <div className="eyebrow">{children}</div>}
function Heading({eyebrow,title,text}:any){return <section className="page-top"><div className="container heading"><Eyebrow>{eyebrow}</Eyebrow><h1>{title}</h1><p className="lead">{text}</p></div></section>}
function List({items}:any){return <ul className="feature-list">{items.map((x:string,i:number)=><li key={i}><Check/>{x}</li>)}</ul>}
function BrandHeader(){const {t,L,lang,setLang,page}=useC();const [open,setOpen]=useState(false);useEffect(()=>setOpen(false),[page]);return <><a href="#main" className="skip" onClick={e=>{e.preventDefault();document.getElementById("main")?.focus()}}>{t('Aller au contenu','Skip to content','Ir al contenido','انتقل إلى المحتوى')}</a><div className="topbar"><div className="container"><span className="topbar-label">{t('Auto-école francophone · London, Ontario','French-speaking driving school · London, Ontario','Autoescuela francófona · London, Ontario','مدرسة تعليم قيادة ناطقة بالفرنسية · لندن، أونتاريو')}</span><div className="topbar-contact"><a href="tel:+12263744883"><Phone/>226 374 4883</a><a href="mailto:francoroute@outlook.com"><Mail/>francoroute@outlook.com</a><a href={routeHref("mon-espace")}><LockKeyhole/>{L('account')}</a><select aria-label={t('Langue du site','Website language','Idioma del sitio','لغة الموقع')} value={lang} onChange={e=>setLang(e.target.value)}><option value="fr">FR · Français</option><option value="en">EN · English</option><option value="es">ES · Español</option><option value="ar">AR · العربية</option></select></div></div></div><header className="header"><div className="container navrow"><a className="brand" href={routeHref("accueil")}><img src={A.logo} alt="FrancoRoute"/><span><b>FrancoRoute</b><small>{t('VOTRE CONFIANCE AU VOLANT','YOUR CONFIDENCE BEHIND THE WHEEL','TU CONFIANZA AL VOLANTE','ثقتك خلف عجلة القيادة')}</small></span></a><button className="menu-toggle" aria-expanded={open} aria-controls="navigation" aria-label={open?L('close'):t('Ouvrir le menu','Open menu','Abrir menú','فتح القائمة')} onClick={()=>setOpen(!open)}>{open?<X/>:<Menu/>}</button><nav id="navigation" className={'nav '+(open?'open':'')} aria-label={t('Navigation principale','Main navigation','Navegación principal','التنقل الرئيسي')}>{[['accueil','home'],['programme-bde','bde'],['tarifs','prices'],['application','app'],['a-propos','about'],['temoignages','reviews'],['contact','contact']].map(([r,k])=><a key={r} href={routeHref(r)} aria-current={page===r?'page':undefined}>{L(k)}</a>)}<a href={routeHref("mon-espace")} className="nav-account">{L('account')}</a><a href={routeHref("reserver")} className="nav-call">{L('call')}</a></nav></div></header></>}
function BrandFooter(){const {t,L}=useC();return <footer className="footer"><div className="container footer-grid"><div><a className="footer-brand" href={routeHref("accueil")}>FrancoRoute</a><p>{L('tagline')}</p><span className="license-tag">{L('licence')} · {t('Programme BDE agréé','Approved BDE program','Programa BDE aprobado','برنامج BDE معتمد')}</span></div><div><h4>{t('Votre prochain pas','Your next step','Tu próximo paso','خطوتك التالية')}</h4><a href={routeHref("programme-bde")}>{L('bde')}</a><a href={routeHref("tarifs")}>{L('prices')}</a><a href={routeHref("application")}>{L('app')} · 28 $ + {t('taxes','tax','impuestos','الضريبة')}</a><a href={routeHref("mon-espace")}>{L('account')}</a></div><div><h4>{t('Parlons de votre projet','Let’s talk about your goals','Hablemos de tu proyecto','لنتحدث عن أهدافك')}</h4><a href="tel:+12263744883">226 374 4883</a><a href="mailto:francoroute@outlook.com">francoroute@outlook.com</a><p>London, Ontario</p></div></div><div className="container footer-bottom"><span>© {new Date().getFullYear()} FrancoRoute Inc.</span><div><a href={routeHref("confidentialite")}>{L('privacy')}</a><a href={routeHref("conditions")}>{L('terms')}</a><span>{L('eastern')}</span></div></div></footer>}
