function Prices(){const {t,L,setModal,money,query}=useC();const offers=useOffers();const [cat,setCat]=useState(query.get('categorie')||'bde');return <><Heading eyebrow={t('Des offres claires, pour chaque étape','Clear options for every stage','Ofertas claras para cada etapa','خيارات واضحة لكل مرحلة')} title={<>{L('prices')}.<br/><em>{t('Choisissez votre prochain pas.','Choose your next step.','Elige tu próximo paso.','اختر خطوتك التالية.')}</em></>} text={t('Programme BDE, pratique, voiture pour l’examen ou préparation en ligne : trouvez l’accompagnement qui vous correspond.','BDE, driving practice, a car for your test or online preparation: find the support that suits you.','BDE, práctica, coche para el examen o preparación en línea: encuentra el apoyo adecuado.','برنامج BDE أو دروس عملية أو سيارة للاختبار أو استعداد عبر الإنترنت: اختر الدعم المناسب لك.')}/><section className="container section"><div className="pricing-tabs" role="group" aria-label={t('Catégories de tarifs','Price categories','Categorías de precios','فئات الأسعار')}>{[['bde',L('bde')],['pratique',t('Leçons & voiture d’examen','Lessons & test car','Clases y coche de examen','الدروس وسيارة الاختبار')],['application',L('app')]].map(([key,title])=><button key={key} className={'chip '+(cat===key?'active':'')} aria-pressed={cat===key} onClick={()=>setCat(key)}>{title}</button>)}</div>{cat==='bde'?<div className="grid3">{offers.filter((o:any)=>o.category==='bde').map((o:any,i:number)=><article className={'price-card '+(i===1?'recommended':'')} key={o.id}><div className="price-head"><span className={'pill '+(i===1?'badge-coral':'')}>{o.tag}</span><h3>{o.name}</h3><p>{o.desc}</p><div className="price">{money(o.cents).replace(' $','')} <small>$ CA</small></div><div className="tax">{L('tax')}</div></div><div className="price-body"><List items={o.items}/><LinkButton to={'reserver?objectif=BDE&forfait='+o.id} kind={i===1?'coral':''}>{L('choose')}</LinkButton><button className="detail-link" onClick={()=>setModal({kind:'offer',id:o.id})}>{L('details')}</button></div></article>)}</div>:cat==='pratique'?<><div className="grid2">{offers.filter((o:any)=>o.category==='pratique').map((o:any)=><article className="mini-price-card" key={o.id}><div><h3>{o.name}</h3><p>{o.desc}</p><button className="btn secondary" onClick={()=>setModal({kind:'offer',id:o.id})}>{L('details')}<ArrowRight size={15}/></button></div><div><div className="price">{money(o.cents)}</div><div className="tax">{L('tax')}</div></div></article>)}</div><div className="note"><Car style={{verticalAlign:'middle',marginInlineEnd:9}} size={20}/>{t('Location / mise à disposition du véhicule pour votre examen : les forfaits G2 et G Full comprennent une heure trente de préparation et une seule présentation à l’examen à London. La réservation et les frais DriveTest restent à votre charge. Hors London : tarif sur demande.','Road test vehicle hire: G2 and full G packages include one and a half hours of preparation and one test appointment in London. DriveTest booking and fees remain your responsibility. Outside London: ask for a quote.','Alquiler / disponibilidad del vehículo: los paquetes G2 y G Full incluyen una hora y media de preparación y una presentación al examen en London. La reserva y los cargos DriveTest son por tu cuenta. Fuera de London: consultar.','استئجار / توفير سيارة للاختبار: تشمل باقات G2 وG الكامل ساعة ونصف من الاستعداد وتقديم اختبار واحد في لندن. حجز DriveTest ورسومه على المتعلّم. خارج لندن: اطلب عرض سعر.')}</div></>:<div className="split"><div><VideoThumb/><div className="actions"><LinkButton to="application" kind="secondary">{t('Tout découvrir sur l’application','Explore everything in the app','Descubrir toda la aplicación','اكتشف كل محتوى التطبيق')}</LinkButton></div></div><AppPrice/></div>}<p className="tax-line">{t('Prix en dollars canadiens, plus taxes. En Ontario : TVH de 13 %. Le détail du montant et des taxes est accessible pour chaque offre.','Prices in Canadian dollars, plus tax. In Ontario: 13% HST. Each offer includes a price and tax breakdown.','Precios en dólares canadienses, más impuestos. En Ontario: HST del 13 %. Cada oferta muestra el desglose.','الأسعار بالدولار الكندي، تضاف إليها الضريبة. في أونتاريو: HST بنسبة 13%. تتوفر تفاصيل المبلغ والضريبة لكل عرض.')}</p>{cat==='bde'&&<div className="note">{t('Les forfaits BDE comprennent les évaluations et la certification après réussite. Les leçons en voiture sont individuelles, sur rendez-vous. Prise en charge et retour à London selon la zone convenue. La voiture d’examen est incluse uniquement dans Confiance et Confiance Plus, pour une présentation au G2. Les frais et la réservation DriveTest sont distincts. L’application à 28 $ + taxes est une offre séparée.','BDE packages include assessments and certification after successful completion. In-car lessons are individual and by appointment. Pick-up and drop-off in London within the agreed area. The test car is included only in Confidence and Confidence Plus, for one G2 test. DriveTest fees and booking are separate. The $28 + tax app is a separate offer.','Los paquetes BDE incluyen evaluaciones y certificación tras completar el programa. Las clases en coche son individuales y con cita. Recogida y regreso en London según la zona acordada. El coche de examen se incluye solo en Confianza y Confianza Plus, para un examen G2. DriveTest se reserva y paga aparte. La aplicación de 28 $ más impuestos es independiente.','تشمل باقات BDE التقييمات والشهادة بعد الإتمام بنجاح. الدروس داخل السيارة فردية وبموعد، مع التوصيل في لندن ضمن المنطقة المتفق عليها. تُدرج سيارة الاختبار في باقتي الثقة وثقة بلس فقط لاختبار G2 واحد. حجز DriveTest ورسومه منفصلان. التطبيق بسعر 28 $ والضريبة عرض مستقل.')}</div>}</section><CallBand/></>}
function AppPrice(){const {t,L,setModal}=useC();return <aside className="application-price" id="acces"><span className="pill"><BookOpen/>G1 · G2 · G FULL</span><div className="price">28 <small>$ CA</small></div><div className="tax">{L('tax')} · {t('TVH de 13 % en Ontario','13% HST in Ontario','HST del 13 % en Ontario','HST بنسبة 13% في أونتاريو')}</div><h3>{t('3 semaines pour vous préparer','3 weeks to get ready','3 semanas para prepararte','3 أسابيع للاستعداد')}</h3><p>{t('21 jours d’accès. Un paiement unique. Sans renouvellement automatique.','21 days of access. One payment. No automatic renewal.','21 días de acceso. Un solo pago. Sin renovación automática.','اشتراك لمدة 21 يوماً. دفعة واحدة. بدون تجديد تلقائي.')}</p><List items={[t('Je prépare / révise mon G1','Prepare and review for G1','Preparo / repaso mi G1','أستعد وأراجع لامتحان G1'),t('Situations G2 et G Full','G2 and full G scenarios','Situaciones G2 y G Full','مواقف G2 وG الكامل'),t('Astuces, exercices et confiance','Tips, exercises and confidence','Consejos, ejercicios y confianza','نصائح وتمارين وثقة'),t('Français, anglais, espagnol et arabe','French, English, Spanish and Arabic','Francés, inglés, español y árabe','الفرنسية والإنجليزية والإسبانية والعربية')]}/><button className="btn coral" onClick={()=>setModal({kind:'offer',id:'application'})}>{t('Choisir mon accès · 28 $ + taxes','Choose access · $28 + tax','Elegir mi acceso · 28 $ + impuestos','اختيار الاشتراك · 28 $ + الضريبة')}<ArrowRight size={17}/></button><p className="subtle" style={{margin:'17px 0 0',fontSize:12}}>{t('En Ontario : 28 $ + 3,64 $ de TVH = 31,64 $.','In Ontario: $28 + $3.64 HST = $31.64.','En Ontario: 28 $ + 3,64 $ HST = 31,64 $.','في أونتاريو: 28 $ + 3.64 $ ضريبة = 31.64 $.')}</p></aside>}
function About(){const {t,L}=useC();return <><Heading eyebrow={t('FrancoRoute · Auto-école francophone','FrancoRoute · French-speaking driving school','FrancoRoute · Autoescuela francófona','FrancoRoute · مدرسة قيادة ناطقة بالفرنسية')} title={<>{t('Une école de conduite.','A driving school.','Una autoescuela.','مدرسة لتعليم القيادة.')}<br/><em>{t('Une rencontre humaine.','A human connection.','Un encuentro humano.','ولقاء إنساني.')}</em></>} text={L('tagline')}/><section className="container section"><div className="split license-layout"><div className="about-copy"><Eyebrow>{t('Qui sommes-nous ?','Who are we?','¿Quiénes somos?','من نحن؟')}</Eyebrow><h2>{t('Votre auto-école francophone à London.','Your French-speaking driving school in London.','Tu autoescuela francófona en London.','مدرستك لتعليم القيادة بالفرنسية في لندن.')}</h2><p>{t('FrancoRoute accompagne les personnes qui veulent apprendre à conduire, préparer leur permis ou retrouver confiance au volant. Nous accueillons chaque parcours avec écoute, patience et respect.','FrancoRoute supports people who want to learn to drive, prepare for a licence or rebuild their confidence behind the wheel. We welcome every journey with listening, patience and respect.','FrancoRoute acompaña a quienes desean aprender a conducir, preparar su permiso o recuperar la confianza al volante. Acogemos cada recorrido con escucha, paciencia y respeto.','يرافق FrancoRoute كل من يريد تعلّم القيادة أو الاستعداد للرخصة أو استعادة الثقة خلف عجلة القيادة. نستقبل كل مسار بالإصغاء والصبر والاحترام.')}</p><p>{t('Notre auto-école francophone est établie à London, en Ontario. Notre programme BDE est agréé par le ministère des Transports de l’Ontario, sous le permis d’école de conduite L3J4.','Our French-speaking driving school is based in London, Ontario. Our BDE program is approved by Ontario’s Ministry of Transportation under driving school licence L3J4.','Nuestra autoescuela francófona está ubicada en London, Ontario. Nuestro programa BDE está aprobado por el Ministerio de Transporte de Ontario con licencia de autoescuela L3J4.','تقع مدرستنا الناطقة بالفرنسية في لندن، أونتاريو. برنامج BDE معتمد من وزارة النقل في أونتاريو بموجب ترخيص مدرسة القيادة L3J4.')}</p><p>{t('Nous croyons que l’apprentissage progresse lorsque l’on peut poser ses questions, comprendre ses erreurs et pratiquer à son rythme. L’autonomie et la sécurité donnent du sens à chaque leçon.','We believe learning grows when you can ask questions, understand mistakes and practise at your own pace. Independence and safety give every lesson purpose.','Creemos que se aprende mejor al poder hacer preguntas, comprender los errores y practicar al propio ritmo. La autonomía y la seguridad dan sentido a cada clase.','نؤمن بأن التعلّم يتقدم عندما تستطيع طرح أسئلتك وفهم أخطائك والتدرّب وفق وتيرتك. والاستقلالية والسلامة هما غاية كل درس.')}</p><div className="approved"><ShieldCheck/><span><b>FRANCOROUTE INC.</b>{L('licence')}</span></div></div><aside className="license-card"><img src={A.licencePreview} alt={t('Licence officielle MTO de FrancoRoute Inc., numéro L3J4','Official MTO licence for FrancoRoute Inc., number L3J4','Licencia oficial MTO de FrancoRoute Inc., número L3J4','ترخيص MTO الرسمي لشركة FrancoRoute Inc. رقم L3J4')}/><div className="license-info"><p className="subtle">{t('Copie publique : adresse masquée pour confidentialité.','Public copy: address withheld for privacy.','Copia pública: dirección oculta por privacidad.','نسخة عامة: حُجب العنوان لحماية الخصوصية.')}</p><b>{t('Notre permis d’école de conduite','Our driving school licence','Nuestra licencia de autoescuela','ترخيص مدرستنا لتعليم القيادة')}</b><small>{t('Délivré le 1er octobre 2026 · Expire le 30 septembre 2029','Issued October 1, 2026 · Expires September 30, 2029','Emitido el 1 de octubre de 2026 · Vence el 30 de septiembre de 2029','صدر في 1 أكتوبر 2026 · ينتهي في 30 سبتمبر 2029')}</small></div><div className="actions"><a className="btn" href={A.pdf} download="FrancoRoute-licence-MTO-L3J4-copie-publique.pdf"><Download/>{t('Licence MTO · copie publique (PDF)','MTO licence · public copy (PDF)','Licencia MTO · copia pública (PDF)','ترخيص MTO · نسخة عامة (PDF)')}</a></div></aside></div><div className="section-head" style={{marginTop:65}}><div><Eyebrow>{t('Nos valeurs, chaque jour','Our values, every day','Nuestros valores, cada día','قيمنا كل يوم')}</Eyebrow><h2>{t('Des valeurs qui se pratiquent.','Values we put into practice.','Valores que se practican.','قيم نطبقها عملياً.')}</h2></div></div><div className="grid2">{[[Users,t('Écoute et respect','Listening and respect','Escucha y respeto','الإصغاء والاحترام'),t('Comprendre vos besoins et vous permettre de poser vos questions sans jugement.','Understand your needs and welcome your questions without judgement.','Comprender tus necesidades y acoger tus preguntas sin juzgarte.','فهم احتياجاتك وإتاحة طرح أسئلتك دون أحكام.'),t('Définir ensemble un objectif pour la leçon.','Set a lesson goal together.','Definir juntos un objetivo para la clase.','تحديد هدف للدرس معاً.')],[HeartHandshake,t('Bienveillance et patience','Kindness and patience','Amabilidad y paciencia','اللطف والصبر'),t('Reconnaître vos efforts, expliquer les erreurs et vous laisser le temps de consolider vos acquis.','Recognise your efforts, explain mistakes and give you time to strengthen your skills.','Reconocer tus esfuerzos, explicar los errores y darte tiempo para consolidar lo aprendido.','تقدير جهودك وشرح الأخطاء ومنحك الوقت لترسيخ مهاراتك.'),t('Décomposer une manœuvre et la reprendre étape par étape.','Break down a manoeuvre and practise it step by step.','Dividir una maniobra y repetirla paso a paso.','تقسيم المناورة والتدرّب عليها خطوة بخطوة.')],[Globe,t('Inclusion et ouverture','Inclusion and openness','Inclusión y apertura','الشمول والانفتاح'),t('Accueillir la diversité des parcours, notamment ceux des nouveaux arrivants.','Welcome diverse journeys, including those of newcomers.','Acoger la diversidad de recorridos, incluidos los de las personas recién llegadas.','استقبال تنوّع المسارات، بما في ذلك مسارات الوافدين الجدد.'),t('Reformuler et utiliser des exemples concrets.','Rephrase and use practical examples.','Reformular y usar ejemplos concretos.','إعادة الشرح واستخدام أمثلة ملموسة.')],[ShieldCheck,t('Autonomie et sécurité','Independence and safety','Autonomía y seguridad','الاستقلالية والسلامة'),t('Vous aider à reconnaître les risques et à prendre des décisions éclairées au volant.','Help you recognise risks and make informed decisions behind the wheel.','Ayudarte a reconocer los riesgos y tomar decisiones informadas al volante.','مساعدتك على إدراك المخاطر واتخاذ قرارات واعية خلف عجلة القيادة.'),t('Observer, choisir une action et comprendre pourquoi.','Observe, choose an action and understand why.','Observar, elegir una acción y comprender por qué.','الملاحظة واختيار التصرف وفهم أسبابه.')]].map(([Icon,title,desc,example]:any)=><article className="value-card" key={title}><Icon/><h3>{title}</h3><p>{desc}</p><div className="example">{example}</div></article>)}</div><div className="quote"><HeartHandshake/>{t('La confiance se construit avec de l’écoute, de la pratique et des petits pas concrets.','Confidence grows through listening, practice and small, meaningful steps.','La confianza se construye con escucha, práctica y pequeños pasos concretos.','تُبنى الثقة بالإصغاء والممارسة والخطوات الصغيرة الملموسة.')}</div></section><CallBand/></>}
const goals=[['Orientation','Premier appel / orientation','First call / guidance','Primera llamada / orientación','مكالمة أولى / توجيه'],['G1','Préparation G1','G1 preparation','Preparación G1','الاستعداد لـ G1'],['BDE','Programme BDE','BDE program','Programa BDE','برنامج BDE'],['G2 / G','Leçons G2 / G Full','G2 / full G lessons','Clases G2 / G Full','دروس G2 / G الكامل'],['Voiture','Voiture pour mon examen','Car for my test','Coche para mi examen','سيارة لاختباري'],['Application','Application · 28 $ + taxes','App · $28 + tax','Aplicación · 28 $ + impuestos','التطبيق · 28 $ + الضريبة']];
type Slot={id:string;starts:number};
async function api(action:string,data?:any){const r=await fetch('/api/'+action,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:undefined,body:data?JSON.stringify(data):undefined,credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(12000)});const d=await r.json();if(!r.ok)throw Object.assign(new Error(d.error||'Service unavailable'),{status:r.status});return d}
function Booking(){const {t,L,lang,query}=useC();const online=true;const [slots,setSlots]=useState<Slot[]>([]),[loading,setLoading]=useState(online),[serviceError,setServiceError]=useState(false),[selected,setSelected]=useState<Slot|null>(null),[selectedDay,setSelectedDay]=useState(''),[month,setMonth]=useState(()=>dayKey(Date.now()/1000).slice(0,7)),[busy,setBusy]=useState(false),[error,setError]=useState(''),[result,setResult]=useState<any>(null),[emailReady,setEmailReady]=useState('');
 const initGoal=query.get('objectif')||'Orientation';const [goal,setGoal]=useState(goals.some(g=>g[0]===initGoal)?initGoal:'Orientation');
 const dateText=(s:number)=>new Intl.DateTimeFormat(locale(lang),{timeZone:tz,weekday:'long',day:'numeric',month:'long'}).format(new Date(s*1000));
 const timeText=(s:number)=>new Intl.DateTimeFormat(locale(lang),{timeZone:tz,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(s*1000));
 async function refresh(){if(!online)return;setLoading(true);setServiceError(false);try{const d=await api('slots');setSlots(d.slots);setSelected(s=>s&&d.slots.some((x:Slot)=>x.id===s.id)?s:null);if(d.slots.length&&!selectedDay){setMonth(dayKey(d.slots[0].starts).slice(0,7));setSelectedDay(dayKey(d.slots[0].starts))}}catch{setServiceError(true)}finally{setLoading(false)}}
 useEffect(()=>{void refresh();if(!online&&slots.length){setSelectedDay(dayKey(slots[0].starts));setMonth(dayKey(slots[0].starts).slice(0,7))}},[]);
 useEffect(()=>{setEmailReady('');setError('')},[selected,goal]);
 const [year,mon]=month.split('-').map(Number),days=new Date(Date.UTC(year,mon,0)).getUTCDate(),offset=(new Date(Date.UTC(year,mon-1,1)).getUTCDay()+6)%7;
 const available=new Set(slots.map(s=>dayKey(s.starts)));const daySlots=slots.filter(s=>dayKey(s.starts)===selectedDay);const currentMonth=dayKey(Date.now()/1000).slice(0,7);
 function changeMonth(delta:number){setMonth(new Date(Date.UTC(year,mon-1+delta,1)).toISOString().slice(0,7));setSelected(null);setSelectedDay('')}
 async function submit(e:any){e.preventDefault();setError('');if(!selected){setError(t('Choisissez une date et un horaire.','Choose a date and time.','Elige una fecha y una hora.','اختر تاريخاً ووقتاً.'));return}const f=new FormData(e.currentTarget);if(f.get('website'))return;const payload={slotId:selected.id,name:String(f.get('name')),email:String(f.get('email')),phone:String(f.get('phone')),topic:['Voiture'].includes(goal)?'G2 / G':goal==='Application'?'G1':goal,consent:f.get('consent')==='on',website:''};setBusy(true);try{const r=await api('bookings',payload);setResult({...r,name:payload.name});setSlots(s=>s.filter(x=>x.id!==selected.id));await refresh()}catch(e:any){setError(e.status===409?t('Cet horaire vient d’être réservé. Choisissez-en un autre.','This time was just booked. Please choose another.','Este horario acaba de reservarse. Elige otro.','حُجز هذا الموعد للتو. اختر موعداً آخر.'):t('La réservation n’a pas été confirmée. Contactez-nous par téléphone ou courriel.','Your booking has not been confirmed. Please contact us by phone or email.','La reserva no se ha confirmado. Contáctanos por teléfono o correo.','لم يتم تأكيد الحجز. اتصل بنا عبر الهاتف أو البريد الإلكتروني.'));if(e.status===409){setSelected(null);await refresh()}}finally{setBusy(false)}}
 function downloadICS(){if(!result)return;const stamp=(s:number)=>new Date(s*1000).toISOString().replace(/[-:]/g,'').replace('.000','');const cancel=location.origin+'/annuler?id='+encodeURIComponent(result.id)+'&token='+encodeURIComponent(result.token);const data=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//FrancoRoute//Premier appel//FR','BEGIN:VEVENT','UID:'+result.id+'@francoroute.com','DTSTAMP:'+stamp(Date.now()/1000),'DTSTART:'+stamp(result.starts),'DTEND:'+stamp(result.starts+900),'SUMMARY:Premier appel FrancoRoute','DESCRIPTION:FrancoRoute vous appelle. Annulation : '+cancel,'END:VEVENT','END:VCALENDAR'].join('\r\n');const url=URL.createObjectURL(new Blob([data],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='FrancoRoute-premier-appel.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 return <><Heading eyebrow={t('Faisons connaissance','Let’s get acquainted','Conozcámonos','لنتعارف')} title={<>{t('Réserver','Book','Reservar','احجز')}<br/><em>{t('un premier appel.','an introductory call.','una primera llamada.','مكالمتك الأولى.')}</em></>} text={t('15 minutes pour comprendre vos besoins, vous orienter et préparer la suite. Du lundi au dimanche, en heure de l’Est.','15 minutes to understand your needs, guide you and plan the next step. Monday to Sunday, Eastern Time.','15 minutos para comprender tus necesidades, orientarte y preparar el siguiente paso. De lunes a domingo, hora del Este.','15 دقيقة لفهم احتياجاتك وتوجيهك وتحديد الخطوة التالية. من الاثنين إلى الأحد، بالتوقيت الشرقي.')}/><section className="container section">{result?<div className="success-panel" role="status"><CheckCircle2/><h2>{t('Votre premier appel est réservé.','Your introductory call is booked.','Tu primera llamada está reservada.','تم حجز مكالمتك الأولى.')}</h2><p>{result.name}, {t('FrancoRoute vous appellera au numéro indiqué.','FrancoRoute will call you at the number you provided.','FrancoRoute te llamará al número indicado.','سيتصل بك FrancoRoute على الرقم الذي قدمته.')}</p><p><b>{dateText(result.starts)} · {timeText(result.starts)}</b><br/>{L('eastern')} · 15 min</p>{result.outlookStatus==='pending'&&<p className="note">{t('La synchronisation Outlook est en cours. Votre créneau reste réservé.','Outlook synchronization is pending. Your time remains reserved.','La sincronización con Outlook está pendiente. Tu horario sigue reservado.','مزامنة Outlook قيد الانتظار. يبقى موعدك محجوزاً.')}</p>}<a className="text-link" href={'/annuler?id='+encodeURIComponent(result.id)+'&token='+encodeURIComponent(result.token)}>{t('Gérer ou annuler cet appel','Manage or cancel this call','Gestionar o cancelar esta llamada','إدارة هذه المكالمة أو إلغاؤها')}</a><br/><button className="btn" onClick={downloadICS}><CalendarDays/>{t('Ajouter à mon calendrier','Add to my calendar','Añadir a mi calendario','أضف إلى تقويمي')}</button></div>:<div className="booking-layout"><aside className="booking-aside"><span className="icon-square"><Phone/></span><h2>{t('Un échange pour vous orienter','A conversation to guide you','Una conversación para orientarte','حوار لمساعدتك على الاختيار')}</h2><p>{t('Vous souhaitez commencer, reprendre confiance ou préparer une prochaine étape ? Faisons le point ensemble.','Starting out, rebuilding confidence or preparing for your next step? Let’s talk it through.','¿Quieres empezar, recuperar confianza o preparar otra etapa? Hablemos juntos.','هل ترغب في البدء أو استعادة الثقة أو الاستعداد لمرحلة جديدة؟ لنتحدث معاً.')}</p><ul className="icon-list"><li><Clock/>15 {t('minutes','minutes','minutos','دقيقة')}</li><li><CalendarDays/>{t('Lundi au dimanche · selon disponibilités','Monday–Sunday · subject to availability','Lunes a domingo · según disponibilidad','الاثنين إلى الأحد · حسب التوفر')}</li><li><Globe/>{L('eastern')}</li><li><Phone/>{t('Nous vous appelons','We call you','Te llamamos','نحن نتصل بك')}</li></ul><div className="contact-links"><a href="tel:+12263744883">226 374 4883</a><a href="mailto:francoroute@outlook.com">francoroute@outlook.com</a></div></aside><div className="booking-main"><div className="booking-title"><h2>1. {t('Choisissez un créneau','Choose a time','Elige un horario','اختر موعداً')}</h2><span className="pill">15 min</span></div>{serviceError?<div className="empty-calendar" role="alert"><p>{t('Le calendrier ne peut pas être chargé actuellement. Contactez-nous pour convenir d’un horaire.','The calendar could not be loaded. Contact us to arrange a time.','No se pudo cargar el calendario. Contáctanos para acordar un horario.','تعذّر تحميل التقويم الآن. اتصل بنا لتحديد موعد.')}</p><a className="btn" href="mailto:francoroute@outlook.com"><Mail/>{L('emailSend')}</a><button className="btn secondary" style={{margin:8}} onClick={refresh}>{t('Réessayer','Retry','Reintentar','أعد المحاولة')}</button></div>:!loading&&slots.length===0?<div className="empty-calendar" role="status"><p>{t('Aucun créneau n’est ouvert pour le moment. Contactez-nous pour fixer un appel.','No times are currently open. Contact us to arrange a call.','No hay horarios disponibles. Contáctanos para concertar una llamada.','لا تتوفر مواعيد حالياً. اتصل بنا لتحديد مكالمة.')}</p><a className="btn" href="tel:+12263744883">226 374 4883</a></div>:loading?<p role="status">{t('Chargement des créneaux…','Loading available times…','Cargando horarios…','جارٍ تحميل المواعيد…')}</p>:<><div className="calendar-layout"><div><div className="calendar-nav"><button className="icon-button" onClick={()=>changeMonth(-1)} disabled={month<=currentMonth} aria-label={t('Mois précédent','Previous month','Mes anterior','الشهر السابق')}><ChevronLeft/></button><strong>{new Intl.DateTimeFormat(locale(lang),{timeZone:'UTC',month:'long',year:'numeric'}).format(new Date(Date.UTC(year,mon-1,1)))}</strong><button className="icon-button" disabled={month>=new Date(Date.now()+179*86400000).toISOString().slice(0,7)} onClick={()=>changeMonth(1)} aria-label={t('Mois suivant','Next month','Mes siguiente','الشهر التالي')}><ChevronRight/></button></div><div className="calendar-grid" role="group" aria-label={t('Calendrier des appels','Call calendar','Calendario de llamadas','تقويم المكالمات')}>{labels.weekdays[langs.indexOf(lang)].map((x:string,i:number)=><span className="weekday" key={'w'+i}>{x}</span>)}{Array.from({length:offset},(_,i)=><span key={'offset'+i}/>)}{Array.from({length:days},(_,i)=>{const day=month+'-'+String(i+1).padStart(2,'0');return <button key={day} disabled={!available.has(day)} className={selectedDay===day?'active':''} aria-pressed={selectedDay===day} aria-label={dateText(zonedEpoch(day,'12:00'))} data-date={day} onClick={()=>{setSelectedDay(day);setSelected(null)}}>{i+1}</button>})}</div><div className="legend"><i/>{online?t('Dates avec des disponibilités','Dates with available times','Fechas con disponibilidad','تواريخ تتوفر فيها مواعيد'):t('Dates proposées · à confirmer','Suggested dates · to be confirmed','Fechas propuestas · por confirmar','تواريخ مقترحة · تحتاج إلى تأكيد')}</div></div><div className="times"><h4>{selectedDay?dateText(zonedEpoch(selectedDay,'12:00')):t('Choisissez une date','Choose a date','Elige una fecha','اختر تاريخاً')}</h4><div className="time-grid">{daySlots.map(s=><button className={'time-btn '+(selected?.id===s.id?'active':'')} key={s.id} aria-pressed={selected?.id===s.id} onClick={()=>setSelected(s)}>{timeText(s.starts)}</button>)}</div><p className="legend-note">{L('eastern')} · {t('Créneaux de 15 min','15-minute slots','Intervalos de 15 min','مواعيد لمدة 15 دقيقة')}</p></div></div>{selected&&<div className="booking-selection" role="status"><CheckCircle2/>{dateText(selected.starts)} · {timeText(selected.starts)} · {L('eastern')}</div>}</>}<form onSubmit={submit} onChange={()=>setEmailReady('')} className="booking-form"><h3>2. {t('Vos coordonnées','Your details','Tus datos','بياناتك')}</h3><div className="field-grid"><label className="field"><span>{L('name')}</span><input name="name" autoComplete="name" required minLength={2} maxLength={100}/></label><label className="field"><span>{L('phone')}</span><input name="phone" type="tel" autoComplete="tel" required minLength={7} maxLength={25}/></label><label className="field"><span>{L('email')}</span><input name="email" type="email" autoComplete="email" required maxLength={254}/></label><label className="field"><span>{L('goal')}</span><select name="goal" value={goal} onChange={e=>setGoal(e.target.value)}>{goals.map(([id,...names])=><option key={id} value={id}>{names[langs.indexOf(lang)]}</option>)}</select></label><div hidden aria-hidden="true"><label>Website<input name="website" tabIndex={-1} autoComplete="off"/></label></div></div><label className="check-label"><input name="consent" type="checkbox" required/><span>{t('J’accepte que FrancoRoute utilise mes coordonnées pour organiser cet appel et me recontacter.','I agree that FrancoRoute may use my details to arrange this call and contact me.','Acepto que FrancoRoute use mis datos para organizar esta llamada y contactarme.','أوافق على استخدام FrancoRoute لبياناتي لتنظيم هذه المكالمة والتواصل معي.')}</span></label><button className="btn" type="submit" disabled={busy||serviceError||loading||!selected}>{busy?t('Réservation…','Booking…','Reservando…','جارٍ الحجز…'):online?t('Confirmer mon premier appel','Confirm my introductory call','Confirmar mi primera llamada','تأكيد مكالمتي الأولى'):t('Préparer ma demande','Prepare my request','Preparar mi solicitud','تجهيز طلبي')}<ArrowRight size={16}/></button>{error&&<p className="error" role="alert">{error}</p>}{emailReady&&<EmailDraft href={emailReady} booking/>}</form></div></div>}</section></>}
function ContactForm(){const {t,L,lang}=useC();const [sent,setSent]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e:any){e.preventDefault();setBusy(true);setError('');const d=new FormData(e.currentTarget);try{await api('contact',{name:d.get('name'),email:d.get('email'),phone:d.get('phone'),goal:d.get('goal'),message:d.get('message')});setSent(true)}catch(err:any){setError(err.message||t('L’envoi a échoué. Réessayez ou appelez-nous.','Sending failed. Try again or call us.','El envío falló. Inténtalo de nuevo o llámanos.','فشل الإرسال. أعد المحاولة أو اتصل بنا.'))}finally{setBusy(false)}}return <form className="form-card" onSubmit={submit} onChange={()=>{setSent(false);setError('')}}><h3>{t('Écrivez-nous','Write to us','Escríbenos','راسلنا')}</h3>{sent?<p className="success" role="status">{t('Votre message a été envoyé. Nous vous répondrons rapidement.','Your message has been sent. We will reply soon.','Tu mensaje ha sido enviado. Te responderemos pronto.','تم إرسال رسالتك. سنرد عليك قريباً.')}</p>:<><div className="field-grid"><label className="field"><span>{L('name')}</span><input name="name" autoComplete="name" required minLength={2} maxLength={100}/></label><label className="field"><span>{L('email')}</span><input name="email" type="email" autoComplete="email" required maxLength={254}/></label><label className="field"><span>{L('phone')}</span><input name="phone" type="tel" autoComplete="tel" required maxLength={25}/></label><label className="field"><span>{L('goal')}</span><select name="goal">{goals.map(([id,...names])=><option key={id} value={id}>{names[langs.indexOf(lang)]}</option>)}</select></label><label className="field full"><span>{L('message')}</span><textarea name="message" required minLength={5} maxLength={2500}/></label></div><label className="check-label"><input type="checkbox" required/><span>{t('J’accepte que FrancoRoute utilise mes coordonnées pour répondre à ma demande.','I agree that FrancoRoute may use my contact details to reply to my request.','Acepto que FrancoRoute use mis datos para responder a mi solicitud.','أوافق على استخدام FrancoRoute لبيانات الاتصال للرد على طلبي.')}</span></label><button className="btn" type="submit" disabled={busy}><Mail/>{busy?t('Envoi…','Sending…','Enviando…','جارٍ الإرسال…'):t('Envoyer mon message','Send my message','Enviar mi mensaje','إرسال رسالتي')}</button>{error&&<p className="error" role="alert">{error}</p>}</>}</form>}
function Contact(){const {t,L}=useC();return <><Heading eyebrow={t('FrancoRoute · London, Ontario','FrancoRoute · London, Ontario','FrancoRoute · London, Ontario','FrancoRoute · لندن، أونتاريو')} title={<>{t('Une question ?','Have a question?','¿Tienes una pregunta?','لديك سؤال؟')}<br/><em>{t('Parlons-en.','Let’s talk.','Hablemos.','لنتحدث.')}</em></>} text={t('Premiers pas, formation BDE, préparation d’examen ou application : nous sommes là pour vous orienter.','First steps, BDE, test preparation or the app: we’re here to guide you.','Primeros pasos, BDE, preparación de examen o aplicación: estamos aquí para orientarte.','خطوات أولى أو BDE أو استعداد للاختبار أو التطبيق: نحن هنا لتوجيهك.')}/><section className="container section split" style={{alignItems:'start'}}><div className="contact-card"><h3>{t('Contactez FrancoRoute','Contact FrancoRoute','Contacta con FrancoRoute','اتصل بـ FrancoRoute')}</h3><a className="contact-item" href="tel:+12263744883"><Phone/>226 374 4883</a><a className="contact-item" href="mailto:francoroute@outlook.com"><Mail/>francoroute@outlook.com</a><div className="contact-item"><MapPin/><span>London, Ontario</span></div><div className="contact-item"><ShieldCheck/>{L('licence')}</div><p className="subtle">{t('Un appel de 15 minutes pour comprendre votre besoin et préparer la suite.','A 15-minute call to understand your needs and plan the next step.','Una llamada de 15 minutos para comprender tus necesidades y preparar el siguiente paso.','مكالمة لمدة 15 دقيقة لفهم احتياجاتك وتحديد الخطوة التالية.')}</p><LinkButton to="reserver">{L('call')}</LinkButton></div><ContactForm/></section></>}
function Reviews(){const {t,L}=useC();const [stars,setStars]=useState(0),[ready,setReady]=useState(''),[error,setError]=useState('');function submit(e:any){e.preventDefault();if(!stars){setError(t('Choisissez une note de 1 à 5 étoiles.','Choose a rating from 1 to 5 stars.','Elige una nota de 1 a 5 estrellas.','اختر تقييماً من نجمة إلى خمس نجوم.'));return}setError('');const f=new FormData(e.currentTarget);setReady(mail('FrancoRoute — témoignage',`Prénom à afficher : ${f.get('name')}\nCourriel de contact (non public) : ${f.get('email')}\nNote : ${stars}/5\nParcours : ${f.get('course')}\n\n${f.get('message')}\n\nJe confirme avoir suivi un service FrancoRoute et j’autorise la publication de mon prénom, de ma note et de mon témoignage. Mon courriel ne doit pas être publié.`))}return <><Heading eyebrow={t('Les parcours qui nous rassemblent','The journeys that bring us together','Los recorridos que nos unen','مسارات تجمعنا')} title={<>{t('Votre expérience compte.','Your experience matters.','Tu experiencia importa.','تجربتك مهمة.')}<br/><em>{t('Partagez-la.','Share it.','Compártela.','شاركها.')}</em></>} text={t('Un mot sur votre parcours peut aider une autre personne à faire son premier pas.','A few words about your journey can help someone else take their first step.','Unas palabras sobre tu recorrido pueden ayudar a otra persona a dar el primer paso.','قد تساعد كلمات عن تجربتك شخصاً آخر على اتخاذ خطوته الأولى.')}/><section className="container section split" style={{alignItems:'start'}}><div className="testimonial-copy"><div className="stars-outline" aria-hidden="true">{Array.from({length:5},(_,i)=><Star key={i}/>)}</div><h2>{t('Votre voix peut encourager un futur conducteur.','Your voice can encourage a future driver.','Tu voz puede animar a un futuro conductor.','قد يشجّع صوتك سائقاً مستقبلياً.')}</h2><p className="lead">{t('L’accueil, les explications, les leçons, les progrès… Racontez ce qui vous a aidé chez FrancoRoute.','The welcome, explanations, lessons, progress… Tell us what helped you at FrancoRoute.','La acogida, las explicaciones, las clases, los progresos… Cuéntanos qué te ayudó en FrancoRoute.','الاستقبال والشروحات والدروس والتقدّم… أخبرنا بما ساعدك في FrancoRoute.')}</p><div className="note">{t('Les témoignages sont publiés avec l’accord de leur auteur, après vérification. Seuls le prénom, la note et le commentaire sont affichés.','Testimonials are published with the author’s permission after review. Only the first name, rating and comment are displayed.','Los testimonios se publican con autorización del autor, tras revisión. Solo se muestran el nombre, la nota y el comentario.','تُنشر الآراء بموافقة أصحابها بعد المراجعة. يُعرض الاسم الأول والتقييم والتعليق فقط.')}</div></div><form className="form-card" onSubmit={submit} onChange={()=>setReady('')}><h3>{t('Laisser un témoignage','Leave a testimonial','Dejar un testimonio','شارك رأيك')}</h3><p className="subtle">{t('Votre note','Your rating','Tu valoración','تقييمك')}</p><div className="star-input" role="group" aria-label={t('Votre note sur 5','Your rating out of 5','Tu valoración sobre 5','تقييمك من 5')}>{[1,2,3,4,5].map(n=><button key={n} type="button" className={n<=stars?'chosen':''} aria-pressed={stars===n} aria-label={t(n+' étoile'+(n>1?'s':''),n+' star'+(n>1?'s':''),n+' estrella'+(n>1?'s':''),n+' من 5 نجوم')} onClick={()=>{setStars(n);setError('');setReady('')}}><Star/></button>)}</div><div className="field-grid"><label className="field"><span>{t('Prénom à afficher','First name to display','Nombre para mostrar','الاسم الأول للعرض')}</span><input name="name" required maxLength={60}/></label><label className="field"><span>{L('email')}</span><input name="email" type="email" required maxLength={254}/></label><label className="field full"><span>{t('Votre parcours','Your course','Tu recorrido','مسارك')}</span><select name="course"><option>BDE</option><option>G1</option><option>G2 / G Full</option><option>{L('app')}</option></select></label><label className="field full"><span>{t('Votre expérience avec FrancoRoute','Your experience with FrancoRoute','Tu experiencia con FrancoRoute','تجربتك مع FrancoRoute')}</span><textarea name="message" required minLength={15} maxLength={2000}/></label></div><label className="check-label"><input type="checkbox" required/><span>{t('J’ai suivi un service FrancoRoute et j’autorise la publication de mon prénom, de ma note et de mon commentaire. Mon courriel reste privé.','I have used a FrancoRoute service and agree to publication of my first name, rating and comment. My email remains private.','He utilizado un servicio FrancoRoute y autorizo la publicación de mi nombre, nota y comentario. Mi correo permanece privado.','استخدمت إحدى خدمات FrancoRoute وأوافق على نشر اسمي الأول وتقييمي وتعليقي. يبقى بريدي الإلكتروني خاصاً.')}</span></label><button type="submit" className="btn">{t('Préparer mon témoignage','Prepare my testimonial','Preparar mi testimonio','تجهيز رأيي')}<ArrowRight size={16}/></button>{error&&<p className="error" role="alert">{error}</p>}{ready&&<EmailDraft href={ready}/>}</form></section></>}
function Legal({privacy=false}:any){const {t,L}=useC();return <><Heading eyebrow="FrancoRoute" title={privacy?L('privacy'):L('terms')} text={privacy?t('Vos informations, avec respect.','Your information, treated with respect.','Tus datos, tratados con respeto.','معلوماتك تُعامل باحترام.'):t('Des informations claires pour préparer votre parcours.','Clear information to plan your journey.','Información clara para preparar tu recorrido.','معلومات واضحة للتخطيط لمسارك.')}/><section className="container section legal-text">{privacy?<><h2>{t('Nous contacter et demander un appel','Contacting us and requesting a call','Contactarnos y solicitar una llamada','التواصل معنا وطلب مكالمة')}</h2><p>{t('Votre nom, votre courriel, votre téléphone et votre objectif servent à répondre à votre demande et à organiser votre accompagnement. Lorsque le formulaire prépare un courriel, vous décidez de son envoi dans votre messagerie.','Your name, email, phone number and goal are used to reply to your request and organise your support. When a form prepares an email, you choose whether to send it from your email app.','Tu nombre, correo, teléfono y objetivo se usan para responder a tu solicitud y organizar el acompañamiento. Cuando el formulario prepara un correo, tú decides enviarlo desde tu aplicación de correo.','يُستخدم اسمك وبريدك وهاتفك وهدفك للرد على طلبك وتنظيم مرافقتك. عندما يجهّز النموذج رسالة بريد، تقرر أنت إرسالها من تطبيق بريدك.')}</p><h2>{L('reviews')}</h2><p>{t('Votre adresse courriel n’est pas publiée. La publication du prénom, de la note et du témoignage demande votre accord. Vous pouvez demander une correction ou un retrait par courriel.','Your email address is not published. Publishing your first name, rating and testimonial requires your consent. You can request a correction or removal by email.','Tu correo no se publica. Publicar tu nombre, valoración y testimonio requiere tu consentimiento. Puedes solicitar una corrección o retirada por correo.','لا يُنشر بريدك الإلكتروني. يتطلب نشر الاسم الأول والتقييم والرأي موافقتك. يمكنك طلب تصحيح أو حذف عبر البريد الإلكتروني.')}</p><h2>{L('app')}</h2><p>{t('Votre compte sert à gérer votre accès et votre progression. Évitez d’inscrire des informations sensibles dans vos notes. Le site conserve votre choix de langue dans ce navigateur.','Your account manages your access and progress. Avoid sensitive information in your notes. The site remembers your language choice in this browser.','Tu cuenta gestiona tu acceso y progreso. Evita datos sensibles en tus notas. El sitio recuerda tu idioma en este navegador.','يدير حسابك الاشتراك والتقدّم. تجنّب المعلومات الحساسة في الملاحظات. يتذكر الموقع لغتك في هذا المتصفح.')}</p></>:<><h2>{t('Tarifs et taxes','Prices and taxes','Precios e impuestos','الأسعار والضرائب')}</h2><p>{t('Les prix sont en dollars canadiens et s’entendent avant taxes. En Ontario, la TVH est de 13 %. L’application est proposée à 28 $ + taxes, soit 31,64 $ avec la TVH de l’Ontario. Le montant total doit être confirmé avant tout paiement.','Prices are in Canadian dollars before tax. Ontario HST is 13%. The app is $28 + tax, or $31.64 including Ontario HST. The total must be confirmed before payment.','Los precios son en dólares canadienses antes de impuestos. El HST de Ontario es del 13 %. La aplicación cuesta 28 $ más impuestos, 31,64 $ con HST de Ontario. El total debe confirmarse antes del pago.','الأسعار بالدولار الكندي قبل الضريبة. تبلغ HST في أونتاريو 13%. التطبيق بسعر 28 $ والضريبة، أي 31.64 $ مع ضريبة أونتاريو. يجب تأكيد الإجمالي قبل الدفع.')}</p><h2>{t('L’accès à l’application','App access','Acceso a la aplicación','الدخول إلى التطبيق')}</h2><p>{t('L’accès personnel dure 21 jours à compter de la confirmation du paiement, sans renouvellement automatique. L’application est un outil pédagogique de préparation au G1, G2 et G Full. Elle ne garantit pas la réussite aux examens et ne remplace pas le programme BDE.','Personal access lasts 21 days from payment confirmation, with no automatic renewal. The app is a learning tool for G1, G2 and full G preparation. It does not guarantee exam success or replace the BDE program.','El acceso personal dura 21 días desde la confirmación del pago, sin renovación automática. La aplicación prepara para G1, G2 y G Full. No garantiza aprobar ni sustituye al programa BDE.','مدة الاشتراك الشخصي 21 يوماً من تأكيد الدفع وبدون تجديد تلقائي. التطبيق أداة للاستعداد لـ G1 وG2 وG الكامل، ولا يضمن النجاح ولا يحل محل BDE.')}</p><h2>{t('Formation et véhicule d’examen','Training and test vehicle','Formación y vehículo de examen','التدريب وسيارة الاختبار')}</h2><p>{t('La certification BDE exige la réussite de toutes les composantes du programme. Les forfaits avec véhicule d’examen couvrent une seule présentation à London. La réservation et les frais de l’examen DriveTest ne sont pas inclus. Les conditions de disponibilité, de modification et d’annulation sont précisées lors de l’inscription.','BDE certification requires successful completion of all program components. Test-car packages cover one test appointment in London. DriveTest booking and exam fees are not included. Availability, changes and cancellation terms are specified when you enrol.','La certificación BDE exige completar con éxito todos los componentes. Los paquetes con vehículo cubren un examen en London. No incluyen reserva ni cargos DriveTest. Las condiciones de disponibilidad, cambios y cancelación se detallan al inscribirse.','تتطلب شهادة BDE إتمام كل مكوّنات البرنامج بنجاح. تغطي باقات سيارة الاختبار اختباراً واحداً في لندن. لا تشمل حجز DriveTest ورسومه. تُوضّح شروط التوفر والتعديل والإلغاء عند التسجيل.')}</p></>}<h2>{t('Une question ou une demande ?','A question or request?','¿Una pregunta o solicitud?','سؤال أو طلب؟')}</h2><p><a href="mailto:francoroute@outlook.com">francoroute@outlook.com</a> · <a href="tel:+12263744883">226 374 4883</a></p></section></>}
function Modal(){const {modal,setModal,t,L,money}=useC();const offers=useOffers();const dialog=useRef<HTMLDivElement>(null);useEffect(()=>{if(!modal)return;const active=document.activeElement as HTMLElement;const prev=document.body.style.overflow;document.body.style.overflow='hidden';dialog.current?.querySelector<HTMLButtonElement>('button')?.focus();function key(e:KeyboardEvent){if(e.key==='Escape')setModal(null);if(e.key==='Tab'){const f=Array.from(dialog.current?.querySelectorAll<HTMLElement>('button,a[href],input,select,textarea,video[controls]')||[]).filter(x=>!x.hasAttribute('disabled'));if(!f.length)return;if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f[f.length-1].focus()}else if(!e.shiftKey&&document.activeElement===f[f.length-1]){e.preventDefault();f[0].focus()}}}document.addEventListener('keydown',key);return()=>{document.body.style.overflow=prev;document.removeEventListener('keydown',key);active?.focus()}},[modal]);if(!modal)return null;const offer=offers.find((o:any)=>o.id===modal.id);return <div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)setModal(null)}}><div role="dialog" aria-modal="true" aria-labelledby="modal-title" className={'modal '+(modal.kind==='video'?'video-modal':'')} ref={dialog}><button className="modal-close" aria-label={L('close')} onClick={()=>setModal(null)}><X/></button>{modal.kind==='video'?<><h2 id="modal-title">{t('Découvrez l’application FrancoRoute','Discover the FrancoRoute app','Descubre la aplicación FrancoRoute','اكتشف تطبيق FrancoRoute')}</h2><video controls autoPlay playsInline preload="metadata" poster={A.appPoster} aria-label={t('Présentation de l’application FrancoRoute en français','FrancoRoute app presentation in French','Presentación de FrancoRoute en francés','عرض تطبيق FrancoRoute باللغة الفرنسية')}><source src={A.video} type="video/mp4"/><source src={A.videoWebm} type="video/webm"/><track default kind="captions" srcLang="fr" label="Français" src={A.captions}/></video><p style={{color:'#d5e7fb',fontSize:12,margin:'10px 0 0'}}>{t('Présentation en français · G1, G2 et G Full','Presentation in French · G1, G2 and full G','Presentación en francés · G1, G2 y G Full','عرض باللغة الفرنسية · G1 وG2 وG الكامل')}</p></>:offer?<><Eyebrow>{t('Votre formule','Your option','Tu opción','خيارك')}</Eyebrow><h2 id="modal-title">{offer.name}</h2><p>{offer.desc}</p><List items={offer.items}/><div className="tax-table"><div><span>{t('Prix avant taxes','Price before tax','Precio antes de impuestos','السعر قبل الضريبة')}</span><b>{money(offer.cents)}</b></div><div><span>{t('TVH · Ontario (13 %)','HST · Ontario (13%)','HST · Ontario (13 %)','HST · أونتاريو (13%)')}</span><b>{money(Math.round(offer.cents*13/100))}</b></div><div><span>{t('Total en Ontario','Total in Ontario','Total en Ontario','الإجمالي في أونتاريو')}</span><b>{money(offer.cents+Math.round(offer.cents*13/100))}</b></div></div><p className="subtle">{offer.category==='application'?t('21 jours d’accès à compter de la confirmation du paiement. Sans renouvellement automatique.','21 days of access from payment confirmation. No automatic renewal.','21 días de acceso desde la confirmación del pago. Sin renovación automática.','21 يوماً من تأكيد الدفع. بدون تجديد تلقائي.'):t('Pour London, Ontario. Frais et réservation DriveTest non inclus. Disponibilités à confirmer avec FrancoRoute.','For London, Ontario. DriveTest fees and booking not included. Confirm availability with FrancoRoute.','Para London, Ontario. No incluye cargos ni reserva DriveTest. Confirma disponibilidad con FrancoRoute.','خاص بلندن، أونتاريو. لا يشمل حجز DriveTest ورسومه. أكّد التوفر مع FrancoRoute.')}</p><div className="actions">{offer.category==='application'?<PurchaseButton/>:<a className="btn" href={'/reserver?objectif='+encodeURIComponent(offer.topic)+'&forfait='+offer.id} onClick={()=>setModal(null)}>{L('call')}<ArrowRight size={16}/></a>}<button className="btn secondary" onClick={()=>setModal(null)}>{t('Continuer ma visite','Keep exploring','Seguir explorando','متابعة التصفح')}</button></div></>:null}</div></div>}

function Application(){const {t,L}=useC();return <><Heading eyebrow={t('Votre espace de préparation','Your preparation space','Tu espacio de preparación','مساحتك للاستعداد')} title={<>{t('Préparez votre permis.','Prepare for your licence.','Prepárate para tu permiso.','استعد لرخصة القيادة.')}<br/><em>{t('Avancez avec confiance.','Move forward with confidence.','Avanza con confianza.','تقدّم بثقة.')}</em></>} text={t('G1, G2 et G Full : des questions, des situations de conduite, des astuces et des exercices pour progresser à votre rythme.','G1, G2 and full G: questions, driving scenarios, tips and exercises to progress at your own pace.','G1, G2 y G Full: preguntas, situaciones de conducción, consejos y ejercicios para avanzar a tu ritmo.','G1 وG2 وG الكامل: أسئلة ومواقف قيادة ونصائح وتمارين للتقدم وفق وتيرتك.')}/><section className="container section"><div className="split app-layout"><div><VideoThumb/><div style={{marginTop:35}}>{[[BookOpen,t('Je comprends','I understand','Comprendo','أفهم'),t('Des thèmes et des explications pour préparer et réviser mon G1.','Topics and explanations to prepare and review for G1.','Temas y explicaciones para preparar y repasar mi G1.','مواضيع وشروحات للاستعداد والمراجعة لامتحان G1.')],[Route,t('Je m’entraîne','I practise','Practico','أتدرّب'),t('Des situations G2 et G Full pour travailler l’observation et les décisions.','G2 and full G scenarios to work on observation and decision-making.','Situaciones G2 y G Full para trabajar la observación y las decisiones.','مواقف G2 وG الكامل للتدرّب على الملاحظة واتخاذ القرار.')],[HeartHandshake,t('Je me prépare','I get ready','Me preparo','أستعد'),t('Des astuces et des exercices pour organiser ma préparation et retrouver mes repères avant l’examen.','Tips and exercises to organise my preparation and feel grounded before the test.','Consejos y ejercicios para organizar mi preparación y sentirme más seguro antes del examen.','نصائح وتمارين لتنظيم استعدادي والشعور بالثبات قبل الاختبار.')],[Target,t('Je vois mes progrès','I see my progress','Veo mis progresos','أتابع تقدّمي'),t('Mes résultats, mes erreurs et mes objectifs dans le même espace.','My results, mistakes and goals in one place.','Mis resultados, errores y objetivos en un mismo espacio.','نتائجي وأخطائي وأهدافي في مساحة واحدة.')]].map(([Icon,title,desc]:any)=><div className="feature-row" key={title}><Icon/><div><h3>{title}</h3><p>{desc}</p></div></div>)}</div><div className="note">{t('L’application complète votre préparation. Elle ne remplace pas le programme BDE ni les examens officiels, et ne délivre pas la certification BDE.','The app supports your preparation. It does not replace the BDE program or official exams and does not issue BDE certification.','La aplicación complementa tu preparación. No sustituye al programa BDE ni a los exámenes oficiales, y no expide la certificación BDE.','يساند التطبيق استعدادك، لكنه لا يحل محل برنامج BDE أو الاختبارات الرسمية ولا يمنح شهادة BDE.')}</div><a href={routeHref("mon-espace")} className="text-link"><LockKeyhole size={15} style={{verticalAlign:'middle',marginInlineEnd:7}}/>{t('Déjà inscrit ? Ouvrir mon espace','Already registered? Open my account','¿Ya tienes cuenta? Abrir mi espacio','لديك حساب؟ افتح مساحتك')}</a></div><AppPrice/></div><div className="faq"><h2>{t('Vos questions, simplement.','Your questions, answered.','Tus preguntas, con claridad.','إجابات واضحة عن أسئلتك.')}</h2>{[[t('Quand commence mon accès ?','When does my access start?','¿Cuándo empieza mi acceso?','متى يبدأ اشتراكي؟'),t('Les 21 jours commencent à la confirmation de votre paiement. Il n’y a pas de renouvellement automatique.','Your 21 days begin when your payment is confirmed. There is no automatic renewal.','Los 21 días empiezan al confirmarse el pago. No hay renovación automática.','تبدأ مدة 21 يوماً عند تأكيد الدفع. ولا يوجد تجديد تلقائي.')],[t('Puis-je utiliser mon téléphone ?','Can I use my phone?','¿Puedo usar mi teléfono?','هل يمكنني استخدام هاتفي؟'),t('Oui. L’application fonctionne sur téléphone, tablette et ordinateur. Une connexion Internet est nécessaire pour votre espace en ligne.','Yes. The app works on phones, tablets and computers. An Internet connection is needed for your online account.','Sí. Funciona en teléfono, tableta y ordenador. Necesitas Internet para acceder a tu espacio en línea.','نعم. يعمل التطبيق على الهاتف والجهاز اللوحي والحاسوب. تحتاج إلى اتصال بالإنترنت لحسابك الإلكتروني.')],[t('Le BDE est-il inclus ?','Is BDE included?','¿Incluye el BDE?','هل يتضمن برنامج BDE؟'),t('L’application à 28 $ + taxes et le programme BDE sont deux offres distinctes. Consultez Nos tarifs pour les forfaits BDE.','The $28 + tax app and the BDE program are separate offers. See Our prices for BDE packages.','La aplicación de 28 $ más impuestos y el programa BDE son ofertas independientes. Consulta Nuestras tarifas.','التطبيق بسعر 28 $ والضريبة وبرنامج BDE عرضان منفصلان. راجع صفحة أسعارنا لباقات BDE.')]].map(([q,a])=><details key={q}><summary>{q}</summary><p>{a}</p></details>)}</div></section><CallBand/></>}

function EmailDraft({href,booking=false}:any){
 const {t,L}=useC();
 const params=new URL(href).searchParams;
 const subject=params.get('subject')||'FrancoRoute';
 const body=params.get('body')||'';
 const [opened,setOpened]=useState(false),[copied,setCopied]=useState(false),[manual,setManual]=useState(false);
 const panel=useRef<HTMLElement>(null),message=useRef<HTMLTextAreaElement>(null);
 useEffect(()=>{setOpened(false);setCopied(false);setManual(false);panel.current?.focus({preventScroll:true});panel.current?.scrollIntoView({behavior:'smooth',block:'nearest'})},[href]);
 async function copy(){try{if(!navigator.clipboard)throw new Error('clipboard');await navigator.clipboard.writeText(body);setCopied(true);setManual(false)}catch{message.current?.focus();message.current?.select();setManual(true)}}
 return <section className="form-status email-draft" tabIndex={-1} ref={panel} aria-label={t('Dernière étape : envoyer votre message','Final step: send your message','Último paso: enviar tu mensaje','الخطوة الأخيرة: إرسال رسالتك')}>
  <h3>{booking?t('3. Envoyez votre demande','3. Send your request','3. Envía tu solicitud','3. أرسل طلبك'):t('Envoyez votre message','Send your message','Envía tu mensaje','أرسل رسالتك')}</h3>
  <p className="email-pending"><Mail size={19}/><strong>{t('Aucun courriel n’a encore été envoyé.','No email has been sent yet.','Todavía no se ha enviado ningún correo.','لم تُرسل أي رسالة بعد.')}</strong></p>
  <p>{t('Ouvrez votre messagerie, puis cliquez sur « Envoyer » dans le courriel qui s’affiche.','Open your email app, then click “Send” in the email that opens.','Abre tu aplicación de correo y pulsa «Enviar» en el mensaje que aparece.','افتح تطبيق بريدك ثم اضغط «إرسال» في الرسالة التي تظهر.')}</p>
  <a href={href} className="btn" onClick={()=>setOpened(true)}><Mail/>{L('emailSend')}</a>
  {opened&&<p role="status" className="draft-guidance">{t('Terminez l’envoi dans votre messagerie. Si rien ne s’ouvre, utilisez le message à copier ci-dessous.','Finish sending in your email app. If nothing opens, use the message to copy below.','Finaliza el envío en tu correo. Si no se abre nada, copia el mensaje de abajo.','أكمل الإرسال في تطبيق بريدك. إذا لم يفتح شيء، انسخ الرسالة أدناه.')}</p>}
  <div className="draft-fallback"><h4>{t('Rien ne s’ouvre ?','Nothing opens?','¿No se abre nada?','لم يفتح شيء؟')}</h4><p>{t('Copiez ce message et envoyez-le depuis votre boîte courriel.','Copy this message and send it from your email account.','Copia este mensaje y envíalo desde tu correo.','انسخ هذه الرسالة وأرسلها من حساب بريدك.')}</p>
  <dl><dt>{t('À','To','Para','إلى')}</dt><dd><bdi>francoroute@outlook.com</bdi></dd><dt>{t('Objet','Subject','Asunto','الموضوع')}</dt><dd>{subject}</dd></dl>
  <label className="field"><span>{t('Message à copier','Message to copy','Mensaje para copiar','رسالة للنسخ')}</span><textarea ref={message} readOnly value={body} rows={8} onFocus={e=>e.currentTarget.select()}/></label>
  <button type="button" className="btn secondary" onClick={copy}>{copied?t('Message copié','Message copied','Mensaje copiado','تم نسخ الرسالة'):t('Copier le message','Copy message','Copiar mensaje','نسخ الرسالة')}</button>
  {copied&&<p role="status">{t('Le message est copié. Collez-le dans un nouveau courriel à FrancoRoute, puis envoyez-le.','Message copied. Paste it into a new email to FrancoRoute, then send it.','Mensaje copiado. Pégalo en un correo nuevo a FrancoRoute y envíalo.','نُسخت الرسالة. ألصقها في رسالة بريد جديدة إلى FrancoRoute ثم أرسلها.')}</p>}
  {manual&&<p role="status">{t('Le texte est sélectionné. Faites Ctrl+C (ou Copier sur votre téléphone), puis collez-le dans votre courriel.','The text is selected. Press Ctrl+C (or Copy on your phone), then paste it into your email.','El texto está seleccionado. Pulsa Ctrl+C (o Copiar en tu móvil) y pégalo en tu correo.','تم تحديد النص. اضغط Ctrl+C أو «نسخ» على هاتفك ثم ألصقه في بريدك.')}</p>}
  </div>
  {booking&&<p className="draft-disclaimer">{t('Le créneau reste à confirmer : il sera réservé uniquement après la réponse de FrancoRoute.','This time is subject to confirmation: it is booked only once FrancoRoute replies.','El horario queda pendiente de confirmación: solo se reserva tras la respuesta de FrancoRoute.','الموعد يحتاج إلى تأكيد ولا يُحجز إلا بعد رد FrancoRoute.')}</p>}
 </section>
}


function routeHref(route:string){
 const [path,query]=route.split('?');
 const aliases:Record<string,string>={accueil:'', 'mon-espace':'espace', valeurs:'a-propos'};
 return '/'+(aliases[path]??path)+(query?'?'+query:'');
}
function MarketingProvider({page='',children}:{page?:string;children:React.ReactNode}){
 const [lang,updateLang]=useState<Lang>('fr'),[query,setQuery]=useState(()=>new URLSearchParams()),[modal,setModal]=useState<any>(null);
 const setLang=(value:Lang)=>{if(!langs.includes(value))return;updateLang(value);try{localStorage.setItem('francoroute-site-language',value)}catch{}window.dispatchEvent(new CustomEvent('fr-language',{detail:value}));};
 useEffect(()=>{
  const restore=()=>{try{const saved=localStorage.getItem('francoroute-site-language') as Lang;if(langs.includes(saved))updateLang(saved)}catch{}};
  restore();setQuery(new URLSearchParams(location.search));
  const changed=(event:Event)=>{const next=(event as CustomEvent).detail;if(langs.includes(next))updateLang(next)};
  const legacy=()=>{const target=location.hash.slice(1),name=target.split('?')[0];if(['accueil','programme-bde','tarifs','application','a-propos','temoignages','contact','mon-espace','reserver','conditions','confidentialite','valeurs'].includes(name))location.replace(routeHref(target));};
  legacy();window.addEventListener('fr-language',changed);window.addEventListener('hashchange',legacy);
  return()=>{window.removeEventListener('fr-language',changed);window.removeEventListener('hashchange',legacy);};
 },[]);
 useEffect(()=>{document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr'},[lang]);
 const t=(...strings:any[])=>strings[langs.indexOf(lang)]??strings[0];
 const L=(key:string)=>(labels as any)[key]?.[langs.indexOf(lang)]??key;
 return <Ctx.Provider value={{page,query,lang,setLang,t,L,money:(cents:number)=>moneyFor(cents,lang),modal,setModal}}><div className="marketing" dir={lang==='ar'?'rtl':'ltr'}>{children}</div></Ctx.Provider>;
}
export function Header({page=''}:{page?:string}){return <MarketingProvider page={page}><BrandHeader/></MarketingProvider>}
export function Footer(){return <MarketingProvider><BrandFooter/></MarketingProvider>}
export default function Website({page}:{page:string}){
 return <MarketingProvider page={page}><BrandHeader/><main id="main" tabIndex={-1}><MarketingPage page={page}/></main><BrandFooter/><Modal/></MarketingProvider>;
}
function MarketingPage({page}:{page:string}){
 const {query}=useC();
 if(page==='programme-bde')return <BDE/>;
 if(page==='tarifs')return <Prices key={query.toString()}/>;
 if(page==='application')return <Application/>;
 if(page==='a-propos'||page==='valeurs')return <About/>;
 if(page==='temoignages')return <Reviews/>;
 if(page==='contact')return <Contact/>;
 if(page==='reserver')return <Booking key={query.toString()}/>;
 if(page==='confidentialite')return <Legal privacy/>;
 if(page==='conditions')return <Legal/>;
 if(page==='annuler')return <CancelCall/>;
 return <Home/>;
}
function PurchaseButton(){
 const {t}=useC();const [config,setConfig]=useState<any>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[accepted,setAccepted]=useState(false);
 useEffect(()=>{api('config').then(setConfig).catch(()=>setError(t('Le paiement est momentanément indisponible. Contactez FrancoRoute.','Payment is currently unavailable. Contact FrancoRoute.','El pago no está disponible. Contacta con FrancoRoute.','الدفع غير متاح حالياً. اتصل بـ FrancoRoute.')))},[]);
 async function buy(){setBusy(true);setError('');try{const result=await api('checkout',{accepted});location.assign(result.url)}catch(e:any){setError(e.message);setBusy(false)}}
 const active=config?.admin||Number(config?.expires)>Date.now()/1000;
 return <div className="purchase-action">
 {active?<a className="btn" href="/espace">{t('Ouvrir mon espace','Open my account','Abrir mi espacio','فتح حسابي')}</a>:config?.paymentReady?<>
 {!config.signedIn?<a className="btn" href="/connexion?next=%2Fapplication%23acces">{t('Me connecter pour acheter','Sign in to buy','Iniciar sesión para comprar','تسجيل الدخول للشراء')}</a>:<><label className="check-label"><input type="checkbox" checked={accepted} onChange={e=>setAccepted(e.target.checked)}/><span>{t('J’accepte les conditions de l’accès de 21 jours.','I accept the terms for 21-day access.','Acepto las condiciones de acceso de 21 días.','أوافق على شروط الاشتراك لمدة 21 يوماً.')} <a href="/conditions" target="_blank" rel="noopener">{t('Lire les conditions','Read terms','Leer las condiciones','قراءة الشروط')}</a></span></label><button className="btn" disabled={!accepted||busy} onClick={buy}>{busy?t('Ouverture du paiement…','Opening checkout…','Abriendo el pago…','جارٍ فتح الدفع…'):t('Payer 28 $ CA + taxes','Pay CA$28 + tax','Pagar 28 $ CA + impuestos','دفع 28 دولاراً كندياً + الضريبة')}</button></>}
 <p className="subtle">{t('Taxes applicables affichées avant de payer.','Applicable taxes shown before payment.','Los impuestos se muestran antes de pagar.','تظهر الضرائب المطبقة قبل الدفع.')}</p>
 </>:<><p role="status">{config||error?t('Les achats en ligne ne sont pas encore disponibles. Contactez-nous pour votre accès.','Online purchases are not available yet. Contact us about access.','Las compras en línea aún no están disponibles. Contáctanos.','الشراء عبر الإنترنت غير متاح بعد. اتصل بنا بشأن الاشتراك.'):t('Chargement…','Loading…','Cargando…','جارٍ التحميل…')}</p><a className="btn" href="/contact">{t('Contacter FrancoRoute','Contact FrancoRoute','Contactar con FrancoRoute','اتصل بـ FrancoRoute')}</a></>}
 {error&&<p className="error" role="alert">{error}</p>}
 </div>;
}
function CancelCall(){
 const {t}=useC();const [busy,setBusy]=useState(false),[cancelled,setCancelled]=useState(false),[message,setMessage]=useState('');
 async function cancel(){setBusy(true);setMessage('');try{const q=new URLSearchParams(location.search);await api('cancel',{id:q.get('id'),token:q.get('token')});setCancelled(true);setMessage(t('Votre rendez-vous est annulé.','Your appointment is cancelled.','Tu cita está cancelada.','تم إلغاء موعدك.'))}catch(e:any){setMessage(e.message)}finally{setBusy(false)}}
 return <section className="container section legal-text"><h1>{t('Gérer mon premier appel','Manage my introductory call','Gestionar mi primera llamada','إدارة مكالمتي الأولى')}</h1><p className="lead">{t('Annulez votre appel pour libérer le créneau.','Cancel your call to release the time.','Cancela tu llamada para liberar el horario.','ألغِ مكالمتك لإتاحة الموعد.')}</p><div className="actions"><button className="btn" disabled={busy||cancelled} onClick={cancel}>{busy?t('Annulation…','Cancelling…','Cancelando…','جارٍ الإلغاء…'):t('Annuler ce rendez-vous','Cancel this appointment','Cancelar esta cita','إلغاء هذا الموعد')}</button><a className="btn secondary" href="/reserver">{t('Choisir un autre créneau','Choose another time','Elegir otro horario','اختيار موعد آخر')}</a></div><p role="status">{message}</p></section>;
}
